package org.hibernate.dialect.identity.spi;

import org.hibernate.SPI;

/// Selects how Hibernate retrieves an identifier generated by an identity
/// column when generated-key retrieval is enabled.
///
/// This choice applies only to identity-generated identifiers. It does not
/// describe retrieval of arbitrary generated columns or the generic
/// post-mutation select performed when Hibernate already knows how to locate
/// the affected row.
///
/// @since 8.0
/// @author Steve Ebersole
@SPI
public enum IdentityValueRetrieval {
	/// Prepare the insert using the JDBC generated-keys flag and let the driver
	/// infer which generated columns to return.
	INFERRED_GENERATED_KEYS,

	/// Prepare the insert with the generated identity column name supplied to
	/// JDBC explicitly.
	NAMED_GENERATED_KEYS,

	/// Apply
	/// [IdentityColumnSupport#appendIdentitySelectToInsert(String, String)] and
	/// execute the completed SQL for a result set.
	///
	/// This is not a later execution of
	/// [IdentityColumnSupport#getIdentitySelectString(String, String, int)].
	APPENDED_SELECT
}
